import os
import torch
from flask import Flask, request, jsonify
from transformers import AutoModelForSequenceClassification, AutoTokenizer

MODEL_DIR = "/app/model_cache/sentiment_model"

app = Flask(__name__)

device = torch.device("cpu")
tokenizer = AutoTokenizer.from_pretrained(MODEL_DIR)
model = AutoModelForSequenceClassification.from_pretrained(MODEL_DIR)
model.to(device)
model.eval()

id2label = model.config.id2label

@app.route("/sentiment", methods=["POST"])
def sentiment():
    try:
        data = request.get_json(silent=True)
        if not data or "text" not in data:
            return jsonify({"error": "Missing 'text' field in JSON body"}), 400
        text = data["text"]
        if not isinstance(text, str) or text.strip() == "":
            return jsonify({"error": "'text' must be a non-empty string"}), 400

        inputs = tokenizer(text, return_tensors="pt", truncation=True, padding=True, max_length=512)
        inputs = {k: v.to(device) for k, v in inputs.items()}
        with torch.no_grad():
            logits = model(**inputs).logits
            probs = torch.softmax(logits, dim=-1).squeeze().tolist()

        labels = [id2label[i] for i in range(len(probs))]
        confidence = {label.lower(): float(prob) for label, prob in zip(labels, probs)}
        positive = confidence.get("positive", 0.0)
        negative = confidence.get("negative", 0.0)
        pred = "positive" if positive >= negative else "negative"

        return jsonify({
            "sentiment": pred,
            "confidence": {
                "positive": positive,
                "negative": negative,
            },
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
